const activePostSaleConversations = new Set(activeConversationIds($('Compras para Coordinacion Comercial').all().map(item => item.json)));
const cfg = $('Config Chatwoot').first().json;
const TZ = 'America/Argentina/Buenos_Aires';

const MAX_ENVIOS = Number(cfg.max_envios_seguimiento ?? 3);
const DIAS_SALTEAR = Number(cfg.dias_inactividad_saltear ?? 45);
const DIAS_CERRAR = Number(cfg.dias_inactividad_cerrar ?? 60);

// Espera despues del ultimo mensaje de la secuencia antes de dar por inactivo.
const ESPERA_INACTIVO = Number(cfg.dias_espera_inactivo ?? 2);
// Margen para no confundir nuestra propia actividad (el mensaje, la etiqueta,
// el atributo) con una respuesta del cliente.
const MARGEN_SEG = 600;

const ahora = $now.setZone(TZ);
const HOY = ahora.toFormat('yyyy-MM-dd');

const norm = (s) => String(s || '').toLowerCase().trim();
const L_SEG = norm(cfg.label_seguimiento);
const L_INACT = norm(cfg.label_inactivo);
const L_BICI = norm(cfg.label_bici);
const L_APAR = norm(cfg.label_aparatos);

// Luxon: 1 = lunes ... 7 = domingo. Por defecto se apaga el domingo.
// Este chequeo tambien vive en el nodo Hoy Se Manda?, antes de la busqueda.
// Queda aca como segunda red por si alguien reconecta la rama directo.
const apagados = String(cfg.dias_sin_envio || '')
  .split(',')
  .map((s) => Number(String(s).trim()))
  .filter((n) => n >= 1 && n <= 7);

if (apagados.includes(ahora.weekday)) {
  console.log('Hoy (weekday ' + ahora.weekday + ') esta en dias_sin_envio. No sale el seguimiento diario.');
  return [];
}

const alias = (v) => String(v || '').split(',').map(norm).filter(Boolean);
const ALIAS_JULI = alias(cfg.alias_juli);
const ALIAS_MARCOS = alias(cfg.alias_marcos);

// SECUENCIA DE 3 PASOS. Lo que elige la plantilla es el NUMERO DE ENVIO, no la
// fecha: envio 1 -> seg_dia_1, envio 2 -> seg_dia_3, envio 3 -> seg_dia_5.
// Por eso si un domingo no sale, el paso siguiente cae el lunes y la cadencia
// no se rompe.
const SECUENCIA = ['seg_dia_1', 'seg_dia_3', 'seg_dia_5'];

const cap = (s) => {
  const t = String(s || '').trim();
  return t ? t.charAt(0).toUpperCase() + t.slice(1) : t;
};

// El nodo de busqueda pagina: llega un item por pagina de Chatwoot.
const convs = $input.all().flatMap((i) => i.json.payload ?? i.json.data?.payload ?? []);

const vistos = new Set();
const salida = [];
let conEtiqueta = 0;
let sinEtiqueta = 0;
let sinVendedor = 0;
let yaHoy = 0;
let aInactivar = 0;
let aTerminar = 0;
let esperandoCierre = 0;
let salteadasPorViejas = 0;
let cerradasPorViejas = 0;
let cerradasPorViejasSinEnvios = 0;

for (const c of convs) {
  // ARROYO: nueva compra registrada evita contacto comercial simultáneo.
  if (activePostSaleConversations.has(String(c.id))) continue;
  if (vistos.has(c.id)) continue;
  vistos.add(c.id);

  const labels = (c.labels ?? []).map(norm).filter(Boolean);
  if (!labels.includes(L_SEG)) { sinEtiqueta++; continue; }
  conEtiqueta++;

  // Marca del ultimo envio. Evita el segundo mensaje si el flujo corre dos
  // veces el mismo dia (prueba manual, reintento, doble activacion).
  const attrs = c.custom_attributes ?? {};
  const ultimoEnvio = String(attrs.seguimiento_ultimo_envio || '');
  if (ultimoEnvio === HOY) { yaHoy++; continue; }

  const enviados = Number(attrs.seguimiento_envios ?? 0);
  const envioNumero = enviados + 1;

  // FILTRO DE ANTIGUEDAD. La etiqueta seguimiento no caduca sola: un vendedor
  // la pone, la charla se enfria y nadie la saca. Al conectar esta rama el
  // 12/09 entraron de golpe conversaciones de hace meses y les salio un
  // "retomo tu consulta" fuera de contexto.
  //   mas de DIAS_CERRAR sin actividad  -> se cierra sacandole seguimiento
  //   mas de DIAS_SALTEAR sin actividad -> no se le manda, pero la etiqueta
  //                                        queda por si el vendedor la retoma
  // Si Chatwoot no informa la fecha, se sigue de largo: preferimos mandar de
  // mas antes que frenar todo por un dato que falta.
  const ultimaActividad = Number(c.last_activity_at ?? c.timestamp ?? 0);
  const diasInactivo = ultimaActividad > 0
    ? Math.floor((ahora.toSeconds() - ultimaActividad) / 86400)
    : null;

  if (diasInactivo !== null && diasInactivo > DIAS_CERRAR) {
    // Solo se marca inactivo al que efectivamente recibio algun mensaje de la
    // secuencia. Si la etiqueta quedo puesta pero nunca salio nada, se cierra
    // sin marcar: no hubo seguimiento del cual no contestar.
    const marcarInactivo = enviados > 0;
    if (marcarInactivo) cerradasPorViejas++; else cerradasPorViejasSinEnvios++;

    const labelsBase = labels.filter((l) => l !== L_SEG && l !== L_INACT);

    salida.push({ json: {
      conversation_id: c.id,
      accion: 'terminar',
      motivo: 'inactiva hace ' + diasInactivo + ' dias' + (marcarInactivo ? ' -> inactivo' : ' (nunca recibio seguimiento)'),
      marcar_inactivo: marcarInactivo,
      ultimo_envio_previo: ultimoEnvio,
      envios_previos: enviados,
      dias_inactivo: diasInactivo,
      labels_finales: marcarInactivo ? [...labelsBase, L_INACT] : labels.filter((l) => l !== L_SEG),
    } });
    continue;
  }

  if (diasInactivo !== null && diasInactivo > DIAS_SALTEAR) {
    salteadasPorViejas++;
    continue;
  }

  // SECUENCIA COMPLETA. Ya recibio los 3 pasos. Antes se cerraba en la corrida
  // del dia siguiente. Ahora se le dan ESPERA_INACTIVO dias mas de aire:
  //   sin respuesta -> se le saca seguimiento y se le pone inactivo
  //   contesto      -> se le saca seguimiento nomas (la secuencia ya termino),
  //                    sin inactivo: respondio y la sigue el vendedor
  // Se cierra aunque no tenga vendedor asignado: si no, quedaria reciclando
  // para siempre en el filtro.
  if (envioNumero > MAX_ENVIOS) {
    const diasDesdeUltimo = ultimoEnvio
      ? Math.floor(ahora.startOf('day').diff(DateTime.fromISO(ultimoEnvio, { zone: TZ }).startOf('day'), 'days').days)
      : null;

    // Todavia dentro de la ventana de espera: no se toca, se mira manana.
    if (diasDesdeUltimo !== null && diasDesdeUltimo < ESPERA_INACTIVO) {
      esperandoCierre++;
      continue;
    }

    // Timestamp exacto del ultimo envio. Las conversaciones que venian de antes
    // de este cambio no lo tienen: se aproxima con la fecha a las 10hs, que es
    // la hora del cron.
    const tsUltimoEnvio = Number(attrs.seguimiento_ultimo_envio_ts ?? 0) ||
      (ultimoEnvio ? DateTime.fromISO(ultimoEnvio + 'T10:00', { zone: TZ }).toSeconds() : 0);

    // Cualquier actividad posterior al ultimo mensaje cuenta como respuesta: en
    // esos dias el flujo no le escribe nada, asi que si algo se movio fue el
    // cliente o el vendedor.
    const contesto = tsUltimoEnvio > 0 && ultimaActividad > tsUltimoEnvio + MARGEN_SEG;

    // Sin fecha del ultimo envio no hay forma de saber si paso la espera: se
    // cierra como siempre, sin marcarlo inactivo.
    const marcarInactivo = !contesto && diasDesdeUltimo !== null;

    // POST /labels reemplaza el set entero, asi que se manda la lista completa
    // MENOS seguimiento (y con inactivo agregado si corresponde). Sin esto se
    // pisarian vendido, bici, cotizado y las demas.
    const labelsBase = labels.filter((l) => l !== L_SEG && l !== L_INACT);

    if (marcarInactivo) aInactivar++; else aTerminar++;

    salida.push({ json: {
      conversation_id: c.id,
      accion: 'terminar',
      motivo: marcarInactivo
        ? 'secuencia completa y ' + diasDesdeUltimo + ' dias sin respuesta -> inactivo'
        : 'secuencia completa (' + enviados + ' envios), hubo actividad despues del ultimo mensaje',
      marcar_inactivo: marcarInactivo,
      ultimo_envio_previo: ultimoEnvio,
      envios_previos: enviados,
      dias_inactivo: diasInactivo,
      dias_desde_ultimo_envio: diasDesdeUltimo,
      labels_finales: marcarInactivo ? [...labelsBase, L_INACT] : labelsBase,
    } });
    continue;
  }

  // ARROYO: dos días calendario entre mensajes; el cron sigue siendo diario.
  // No recuperar todos los pasos atrasados ni adivinar fechas faltantes.
  const DIAS_ENTRE_ENVIOS = 2;
  const diaAnterior = Date.parse(ultimoEnvio + 'T00:00:00Z');
  const diasDesdeEnvio = (Date.parse(HOY + 'T00:00:00Z') - diaAnterior) / 86400000;
  if (enviados > 0 && (!Number.isFinite(diasDesdeEnvio) || diasDesdeEnvio < DIAS_ENTRE_ENVIOS)) continue;

  const asignado = norm(c.meta?.assignee?.available_name ?? c.meta?.assignee?.name ?? '');

  let quien = '';
  if (ALIAS_JULI.some((a) => asignado.includes(a))) quien = 'juli';
  else if (ALIAS_MARCOS.some((a) => asignado.includes(a))) quien = 'marcos';

  // Sin Juli ni Marcos asignado no se manda: la plantilla la firma una persona
  // y no corresponde que salga de un chat que atendio otro.
  if (!quien) { sinVendedor++; continue; }

  // Las tres plantillas nuevas NO usan el nombre del cliente, solo asesor y
  // producto. Por eso ya no se descarta a quien Chatwoot guardo con el
  // telefono en vez del nombre: ese saludo feo no existe mas.
  const asesor = cap(quien);

  // El producto sale de las etiquetas de rubro que pone el sub-flujo
  // "arroyo v2 - etiquetar conversacion". Sin rubro va el texto generico:
  // la frase de la plantilla es fija y Meta RECHAZA una variable vacia.
  let producto;
  if (labels.includes(L_BICI)) producto = cfg.producto_bici;
  else if (labels.includes(L_APAR)) producto = cfg.producto_aparatos;
  else producto = cfg.producto_generico;

  const templateMessage = commercialTemplate($('Compras para Coordinacion Comercial').first().json.config.commercial_templates?.[String(c.inbox_id)], SECUENCIA[envioNumero - 1], cfg.template_language, { asesor, producto });
  salida.push({ json: {
    conversation_id: c.id,
    accion: 'enviar',
    nombre: String(c.meta?.sender?.name ?? '').trim().split(' ')[0],
    vendedor: quien,
    asesor: asesor,
    producto: producto,
    asignado_a: asignado,
    ultimo_envio_previo: ultimoEnvio,
    dias_inactivo: diasInactivo,
    paso: envioNumero,
    template_name: SECUENCIA[envioNumero - 1],
    template_category: templateMessage.category,
    template_language: templateMessage.language,
    // Las claves tienen que coincidir EXACTO con las variables de la plantilla
    // aprobada en Meta, o el envio se rechaza.
    processed_params: templateMessage.processed_params,
    template_content: templateMessage.content,
    envio_numero: envioNumero,
    fecha_envio: HOY
  } });
}

// ARROYO: procesar todos los elegibles, uno por vez en el bucle de envío.
salida.sort((a, b) => String(a.json.ultimo_envio_previo).localeCompare(String(b.json.ultimo_envio_previo)));
console.log('Conversaciones evaluadas: ' + vistos.size + ' | acciones elegibles: ' + salida.length + ' | ya enviadas hoy: ' + yaHoy + ' | sin vendedor: ' + sinVendedor);
return salida;
